  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const params = args && typeof args === 'object' ? args : {};

  for (const key of Object.keys(params)) {
    if (key !== 'user_ids') {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const { user_ids } = params;

