import('./server.mjs').then(async ({listTools, callTool}) => {
  const tools = await listTools();
  console.log('TOOLS:', JSON.stringify(tools.map(t => t.name)));
  console.log('SCHEMA addlProps:', tools[0].inputSchema.additionalProperties);

  // Happy path - mixed found/missing
  let r = await callTool('users_get_many', {user_ids:['u2','missing']});
  console.log('OK:', r.content[0].text);

  // Duplicate
  try { await callTool('users_get_many', {user_ids:['u1','u1']}); console.log('DUP NOT REJECTED'); }
  catch(e){ console.log('DUP REJECTED:', e.message); }

  // Empty
  try { await callTool('users_get_many', {user_ids:[]}); console.log('EMPTY NOT REJECTED'); }
  catch(e){ console.log('EMPTY REJECTED:', e.message); }

  // Too many
  try { await callTool('users_get_many', {user_ids:['u1','u2','u3','u1','u2','u3']}); console.log('MANY NOT REJECTED'); }
  catch(e){ console.log('MANY REJECTED:', e.message); }

  // Non-string
  try { await callTool('users_get_many', {user_ids:[1,2]}); console.log('NUM NOT REJECTED'); }
  catch(e){ console.log('NUM REJECTED:', e.message); }

  // Extra field
  try { await callTool('users_get_many', {user_ids:['u1'], foo:'bar'}); console.log('EXTRA NOT REJECTED'); }
  catch(e){ console.log('EXTRA REJECTED:', e.message); }

  // Not array
  try { await callTool('users_get_many', {user_ids:'u1'}); console.log('STR NOT REJECTED'); }
  catch(e){ console.log('STR REJECTED:', e.message); }

  // Missing arg
  try { await callTool('users_get_many', {}); console.log('MISSING NOT REJECTED'); }
  catch(e){ console.log('MISSING REJECTED:', e.message); }

  // Unknown tool
  try { await callTool('bogus', {user_ids:['u1']}); console.log('UNKNOWN TOOL NOT REJECTED'); }
  catch(e){ console.log('UNKNOWN TOOL REJECTED:', e.message); }

  // Order preserved
  r = await callTool('users_get_many', {user_ids:['u3','u1','u2']});
  console.log('ORDER:', r.content[0].text);
});
" 2>&1"}

